// Local design fixtures only. No model, upload, payment or production writes.
window.SaryBrainPreview = (() => {
  const storageKey='sary-brain-preview-v1';
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const seed={version:1,files:[{id:'policy'},{id:'catalog'},{id:'guide'},{id:'legacy'},{id:'scan'}],gaps:[]};
  let data=JSON.parse(JSON.stringify(seed)),section='overview',salesPanel='operations';
  try { const stored=JSON.parse(localStorage.getItem(storageKey)||'null');if(stored?.version===1&&Array.isArray(stored.files)&&stored.files.every(f=>typeof f.id==='string'))data=stored; } catch {}
  const persist=()=>{try{localStorage.setItem(storageKey,JSON.stringify(data));}catch{toast('تعذر الحفظ في المتصفح. بقيت تغييرات المثال خلال الجلسة.');}};
  const button=(text,action,id='',primary=false,extra='')=>'<button type="button" class="button '+(primary?'primary':'')+'" data-brain-action="'+action+'" data-id="'+escape(id)+'" '+extra+'>'+escape(text)+'</button>';
  const close=()=>document.getElementById('dialog').close();
  const tabs=[['overview','الملخص'],['sources','المصادر والملفات'],['knowledge','المعرفة والفجوات'],['sales','احتراف المبيعات'],['testing','التجربة والجودة'],['history','سجل التغييرات']];
  const help={overview:'ابدأ بحالة المعرفة والأدلة والخطوة التي تحتاج اهتمامك.',sources:'راجع الملفات ونتائج الاستخراج والمصادر قبل اعتماد المعرفة.',knowledge:'راجع الأقسام والتعارضات والأسئلة وصفحات الموقع.',sales:'راجع معرفة البيع وسياساته وتجربته. لا توجد نسبة احتراف مثبتة.',testing:'جرّب الردود وراجع سجل التوليد؛ نجاح الطلب لا يثبت جودة الإجابة.',history:'راجع الأنشطة المحفوظة والفلاتر وتفاصيل التغيير.'};
  const route=()=>{const params=new URLSearchParams(location.hash.split('?')[1]||'');return {view:tabs.some(t=>t[0]===params.get('view'))?params.get('view'):'overview',pane:['sections','conflicts','faq','pages'].includes(params.get('pane'))?params.get('pane'):'sections'};};
  function refresh(focusId){const root=document.querySelector('[data-brain-workspace]');if(!root)return;root.outerHTML=render();if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});}
  function navigate(target,pane){
    const aliases={results:'overview',files:'sources',gaps:'knowledge',learning:'sales',operations:'sales'};
    if(target==='learning'||target==='operations')salesPanel=target;
    target=aliases[target]||target;if(!tabs.some(t=>t[0]===target))return;
    const params=new URLSearchParams(location.hash.split('?')[1]||'');params.set('view',target);
    if(pane&&['sections','conflicts','faq','pages'].includes(pane))params.set('pane',pane);
    const hash='#/page/merchant/sari-brain?'+params.toString();
    if(location.hash!==hash)history.pushState(history.state,'',hash);
    section=target;refresh('brain-nav-'+target);
  }
  const preview=(title,href,description)=>'<article class="panel panel-pad brain-current-card"><h2>'+title+'</h2><p>'+description+'</p><a class="button" href="'+href+'">فتح الشاشة التفاعلية</a></article>';
  const removal=()=>preview('مراجعة حذف المعرفة وإعادة الضبط','./knowledge-removal.html','مكوّن التطبيق نفسه: مراجعة الأثر ثم الإيصال واستعادة الطلب غير المؤكد. لا حذف فعلي.');
  function render(){
    const current=route();section=current.view;
    let content='';
    if(section==='overview')content=window.SaryBrainWorkbench.learningStatus()+window.SaryBrainWorkbench.renderSourceInventory()+preview('نتائج تحليل الموقع','./website-analysis.html','نتائج القراءة والتصنيف منفصلة، مع حالات الخطأ والنتيجة غير المطابقة للمحاولة.')+button('مراجعة مقترحات التعلّم','navigate','learning');
    if(section==='sources')content=preview('مجموعات مصادر المعرفة','./knowledge-groups.html','بطاقات التطبيق الفعلية للملفات والكتالوج والموقع والأسئلة والأقسام وإعدادات النشاط.')+window.SaryBrainWorkbench.render('sources')+removal();
    if(section==='knowledge')content=window.SaryBrainWorkbench.render('knowledge',current.pane);
    if(section==='sales')content='<section class="panel panel-pad"><h2>احتراف المبيعات</h2><p class="brain-current-score"><strong>—</strong> غير متاح حاليًا</p><p>لا توجد نسبة موثوقة تجمع مهارات البيع في المحادثات الفعلية. راجع المعرفة والردود والتجارب قبل تقييم الأداء.</p><div class="brain-current-links">'+button('التجربة والجودة','navigate','testing')+button('المعرفة والفجوات','navigate','knowledge')+'</div></section>'+preview('معرفة البيع وفرص التحسين','./sales-knowledge.html','عرض مكوّن التطبيق للأقسام ومصادرها وتواريخها وحدودها، دون تحويلها إلى درجة مبيعات.')+'<nav class="brain-current-links" aria-label="إدارة المبيعات">'+button('سياسات وتجارب وردود البيع','navigate','operations')+button('مراجعات مقترحات التعلّم','navigate','learning')+'</nav>'+(salesPanel==='learning'?learning():window.SaryBrainWorkbench.render('operations'));
    if(section==='testing')content=preview('الاختبار السريع','./brain-preview.html','مكوّن التطبيق نفسه مع حفظ المسودة وحالات الانتظار والفشل وحدود الاستجابة.')+preview('سجل توليد الردود','./reply-quality.html','الأرقام تصف محاولات التوليد وعينتها؛ لا تقيس تلقائيًا جودة الرد أو الإقناع.');
    if(section==='history')content=preview('سجل نشاط ساري','./knowledge-activity.html','مكوّن التطبيق للبحث بنوع النشاط والترقيم والتواريخ غير المتاحة وعزل بيانات التيننت.')+'<details><summary>سجل تغييرات المثال المحلي</summary>'+window.SaryBrainWorkbench.render('history')+'</details>';
    return '<section class="brain-workspace" data-brain-workspace><nav class="brain-nav" aria-label="أقسام عقل ساري">'+tabs.map(([id,title])=>'<button type="button" id="brain-nav-'+id+'" data-brain-action="navigate" data-id="'+id+'" aria-pressed="'+(section===id)+'">'+title+'</button>').join('')+'</nav><p role="status">'+help[section]+'</p><div id="brain-section" class="brain-current-section">'+content+'</div><p class="brain-footnote">معاينة محلية. الشاشات المرتبطة تستخدم مكونات التطبيق؛ بقية سيناريوهات التحرير محاكاة مستقلة ولا تتزامن بياناتها تلقائيًا مع المعاينات الأخرى.</p></section>';
  }
  function openAdd(){navigate('sources');document.querySelector('[data-kd-document]')?.scrollIntoView?.({block:'start'});document.querySelector('[data-kd-document] input,[data-kd-document] button')?.focus();}
  const reviewCases=['فهم الاحتياج','المقارنة بين الخيارات','اعتراض السعر','الموافقة على المتابعة','احترام رفض العميل','صحة المعلومات','التحويل إلى موظف','التعليمات المخالفة داخل الرسالة'];
  let reviewStep=0,reviewDraft=data.review?.cases?.length===8?JSON.parse(JSON.stringify(data.review.cases)):reviewCases.map(()=>({baseline:'',candidate:'',baselineVerdict:'',candidateVerdict:'',reason:''}));
  function reviewComplete(r){return r.baseline.trim()&&r.baseline.length<=2000&&r.candidate.trim()&&r.candidate.length<=2000&&['pass','fail'].includes(r.baselineVerdict)&&['pass','fail'].includes(r.candidateVerdict)&&r.reason.trim().length>=20&&r.reason.length<=1000;}
  function learning(){return window.SaryBrainWorkbench.learningStatus()+'<section class="panel panel-pad"><h2>اقتراح لتحسين أسلوب البيع</h2><p>مثال توضيحي: سؤال العميل عن أداة التحضير قبل اقتراح الطحن. الاقتراح يحتاج مراجعة بشرية، ولا يصبح تعليمات فعالة تلقائيًا.</p><details><summary>الأدلة المؤيدة والمخالفة</summary><blockquote>العميل: عندي أداة تقطير وأحتاج طحن مناسب.</blockquote><blockquote>حالة مخالفة: عميل متكرر طلب إعادة نفس الطحن؛ السؤال مرة أخرى غير ضروري.</blockquote></details><h3>مراجعة مستقلة من 8 حالات</h3><p>قارن الرد الحالي والمقترح، دوّن الحكم والسبب، ثم راجع النتيجة. الحفظ لا يطلق تجربة ولا يرسل رسالة.</p>'+button('ابدأ / أكمل المراجعة','review-open')+(data.review?'<p role="status">آخر نتيجة محلية: '+escape(data.review.outcome)+' · لا تُغيّر نسبة احتراف المبيعات.</p>':'')+'<div class="as-note"><h3>تجارب المبيعات والردود</h3><p>في التطبيق: تصميم التجربة، حجم العينة، تأهيل الجمهور، التسجيل، المراجعة، التشغيل والسحب، ثم مراجعة الرد قبل إرساله. يمكنك مراجعة خطواتها محليًا من قسم تشغيل المبيعات.</p>'+button('فتح تشغيل المبيعات','navigate','operations')+'<a href="#/page/merchant/bot-settings">سياسات الخصم والهامش وإعدادات الرد ←</a></div></section>';}
  function reviewDialog(){
    const r=reviewDraft[reviewStep],done=reviewDraft.filter(reviewComplete).length;
    openDialog('مراجعة التعلم · مثال محلي', '<form class="form-stack" data-brain-form="review"><p>الحالة '+(reviewStep+1)+' من 8 · '+done+' مكتملة</p><h3>'+reviewCases[reviewStep]+'</h3>'+[['baseline','الرد الحالي'],['candidate','الرد المقترح'],['reason','سبب الحكم']].map(([key,label])=>'<label for="brain-review-'+key+'">'+label+'</label><textarea id="brain-review-'+key+'" data-review-field="'+key+'" required maxlength="'+(key==='reason'?1000:2000)+'" '+(key==='reason'?'minlength="20"':'')+'>'+escape(r[key])+'</textarea>').join('')+[['baselineVerdict','حكم الرد الحالي'],['candidateVerdict','حكم الرد المقترح']].map(([key,label])=>'<label for="brain-review-'+key+'">'+label+'</label><select id="brain-review-'+key+'" data-review-field="'+key+'" required>'+[['','اختر الحكم'],['pass','اجتاز'],['fail','لم يجتز']].map(([value,label])=>'<option value="'+value+'" '+(r[key]===value?'selected':'')+'>'+label+'</option>').join('')+'</select>').join('')+'<div class="dialog-foot">'+button('السابق','review-prev','','',reviewStep===0?'disabled':'')+button('التالي','review-next','','',reviewStep===7?'disabled':'')+'</div><label class="check-label"><input id="brain-review-attest" type="checkbox" required>راجعت الردين والحكم لكل الحالات الثماني</label><button class="button primary" type="submit">حفظ نتيجة المراجعة المحلية</button><p id="brain-review-error" role="alert"></p></form>');
  }
  document.addEventListener('input',event=>{if(event.target.dataset.reviewField){reviewDraft[reviewStep][event.target.dataset.reviewField]=event.target.value;const checkbox=document.getElementById('brain-review-attest');if(checkbox)checkbox.checked=false;}});
  document.addEventListener('change',event=>{if(event.target.dataset.reviewField){reviewDraft[reviewStep][event.target.dataset.reviewField]=event.target.value;document.getElementById('brain-review-attest').checked=false;}});
  document.addEventListener('submit',event=>{if(event.target.dataset.brainForm!=='review')return;event.preventDefault();if(!reviewDraft.every(reviewComplete)){document.getElementById('brain-review-error').textContent='أكمل الردين والحكم وسببًا من 20 إلى 1000 حرف في كل الحالات الثماني.';return;}if(!document.getElementById('brain-review-attest').checked)return;data.review={outcome:reviewDraft.every(r=>r.candidateVerdict==='pass')?'اجتاز التقييم التوضيحي':'لم يجتز التقييم التوضيحي',cases:JSON.parse(JSON.stringify(reviewDraft))};persist();window.SaryBrainWorkbench?.reviewSaved(data.review);close();refresh();});


  document.addEventListener('click',event=>{const target=event.target.closest('[data-brain-action]');if(!target||target.disabled)return;const {brainAction:action,id}=target.dataset;if(action==='navigate')navigate(id);if(action==='review-open')reviewDialog();if(action==='review-prev'||action==='review-next'){reviewStep=Math.max(0,Math.min(7,reviewStep+(action==='review-prev'?-1:1)));reviewDialog();}});
  function reset(){data=JSON.parse(JSON.stringify(seed));section='overview';salesPanel='operations';reviewStep=0;reviewDraft=reviewCases.map(()=>({baseline:'',candidate:'',baselineVerdict:'',candidateVerdict:'',reason:''}));window.SaryBrainWorkbench?.reset();persist();}
  function removeSourceExamples(kind){if(kind==='all')data.files=[];else if(kind==='document')data.files=data.files.filter(f=>f.id==='catalog');else if(kind==='products')data.files=data.files.filter(f=>f.id!=='catalog');delete data.review;reviewStep=0;reviewDraft=reviewCases.map(()=>({baseline:'',candidate:'',baselineVerdict:'',candidateVerdict:'',reason:''}));persist();}
  return {render,refresh,navigate,openAdd,reset,reviewResult:()=>data.review,sourceCounts:()=>({document:data.files.filter(f=>f.id!=='catalog').length,products:data.files.filter(f=>f.id==='catalog').length}),removeSourceExamples};
})();
